insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('gate-3ft', '3-Foot Gate', 'putting', '20 putts from 3ft through a tee gate one putter-head wide. Score = % holed.', '{"scoring":"percent_success","reps":20,"targets":{"5":90,"10":85,"15":75,"20":65,"25":55,"scratch":95}}', 10);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('circle-5ft', '5-Foot Circle', 'putting', '12 putts from 5ft around the hole (clock drill). Score = % holed.', '{"scoring":"percent_success","reps":12,"targets":{"5":75,"10":65,"15":55,"20":45,"25":35,"scratch":85}}', 12);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('ladder-lag', 'Lag Ladder 20/30/40', 'putting', '3 putts each from 20/30/40ft. 3pts inside 2ft, 1pt inside 3ft. Score = points ÷ max.', '{"scoring":"points","reps":9,"targets":{"5":70,"10":60,"15":50,"20":42,"25":35,"scratch":80}}', 12);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('no-three-putt-18', '18-Hole No-3-Putt', 'putting', '18 lag putts from 25–50ft. Success = 2 putts or fewer.', '{"scoring":"percent_success","reps":18,"targets":{"5":90,"10":85,"15":78,"20":70,"25":60,"scratch":95}}', 20);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('breaker-8ft', 'Breaking 8-Footers', 'putting', '16 putts from 8ft, 4 from each compass point of a sloped hole.', '{"scoring":"percent_success","reps":16,"targets":{"5":52,"10":45,"15":38,"20":30,"25":25,"scratch":60}}', 15);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('speed-control-40', 'Dead-Weight 40s', 'putting', '10 putts from 40ft finishing in a 3ft-past window. Never short.', '{"scoring":"percent_success","reps":10,"targets":{"5":70,"10":60,"15":50,"20":42,"25":35,"scratch":80}}', 10);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('one-hand-6ft', 'One-Hand Release', 'putting', '10 trail-hand-only putts from 6ft to train release.', '{"scoring":"percent_success","reps":10,"targets":{"5":60,"10":50,"15":42,"20":35,"25":28,"scratch":70}}', 8);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('updown-test', 'Up-&-Down Test', 'short_game', '9 balls from varied greenside lies. Success = hole out in ≤2 (chip + putt).', '{"scoring":"percent_success","reps":9,"targets":{"5":55,"10":44,"15":33,"20":25,"25":18,"scratch":67}}', 25);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('landing-towel', 'Landing-Spot Towel', 'short_game', '15 chips landing on a towel at your chosen spot. Score = % on towel.', '{"scoring":"percent_success","reps":15,"targets":{"5":50,"10":40,"15":33,"20":26,"25":20,"scratch":60}}', 15);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('sand-save-9', 'Sand Save Nine', 'short_game', '9 bunker shots. Success = ball inside 9ft.', '{"scoring":"percent_success","reps":9,"targets":{"5":45,"10":35,"15":27,"20":20,"25":14,"scratch":55}}', 20);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('par-18', 'Par-18 Short Course', 'short_game', '9 greenside holes, par 2 each. Score = (36 − strokes over 18) mapped to 100.', '{"scoring":"points","reps":9,"targets":{"5":67,"10":56,"15":47,"20":39,"25":31,"scratch":78}}', 30);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('flop-carry', 'Flop Carry Control', 'short_game', '10 flop shots carrying a bag 5yd away, stopping inside 12ft.', '{"scoring":"percent_success","reps":10,"targets":{"5":40,"10":32,"15":25,"20":18,"25":12,"scratch":50}}', 15);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('chip-3-clubs', 'Three-Club Chipping', 'short_game', 'Same target with PW/9i/8i, 4 balls each. Success = inside 6ft.', '{"scoring":"percent_success","reps":12,"targets":{"5":48,"10":40,"15":32,"20":25,"25":18,"scratch":58}}', 15);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('worst-lie-updown', 'Worst-Lie Up-&-Down', 'short_game', '6 balls thrown into trouble; play them as they lie. Success = up-and-down.', '{"scoring":"percent_success","reps":6,"targets":{"5":35,"10":27,"15":20,"20":14,"25":9,"scratch":45}}', 15);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('wedge-matrix', 'Wedge Distance Matrix', 'wedges', '3 balls each to 40/60/80/100yd targets. Score from average % distance error.', '{"scoring":"distance_error","reps":12,"targets":{"5":74,"10":66,"15":58,"20":50,"25":42,"scratch":82}}', 25);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('clock-swings', 'Clock-Face Carries', 'wedges', '9:00/10:30/12:00 swings with one wedge, 3 balls each; call carry before each.', '{"scoring":"distance_error","reps":9,"targets":{"5":72,"10":64,"15":56,"20":48,"25":40,"scratch":80}}', 20);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('trajectory-windows', 'Trajectory Windows', 'wedges', '12 shots alternating low/mid/high to one 60yd target; success = correct window + inside 20ft.', '{"scoring":"percent_success","reps":12,"targets":{"5":46,"10":38,"15":30,"20":23,"25":17,"scratch":55}}', 20);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('one-ball-course', 'One-Ball Wedge Course', 'wedges', '10 random distances 30–110yd, one ball each. 3pts <10ft, 2pts <20ft, 1pt on green.', '{"scoring":"points","reps":10,"targets":{"5":66,"10":57,"15":48,"20":40,"25":32,"scratch":75}}', 25);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('spin-check', 'Check-and-Release', 'wedges', '10 half-wedges that stop within 6ft of pitch mark.', '{"scoring":"percent_success","reps":10,"targets":{"5":42,"10":34,"15":27,"20":20,"25":14,"scratch":50}}', 15);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('gir-sim-9', '9-Hole GIR Simulator', 'approach', '9 approaches at range targets matching your course''s approach distances. Success = on ''green'' window.', '{"scoring":"percent_success","reps":9,"targets":{"5":55,"10":44,"15":36,"20":28,"25":20,"scratch":67}}', 25);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('nine-shot', 'Nine-Shot Drill', 'approach', 'Draw/straight/fade × low/mid/high with a 7-iron. Success = called shape flies.', '{"scoring":"percent_success","reps":9,"targets":{"5":44,"10":33,"15":25,"20":18,"25":12,"scratch":55}}', 20);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('proximity-150', '150 Proximity', 'approach', '10 balls to a 150yd target; score from average proximity.', '{"scoring":"distance_error","reps":10,"targets":{"5":70,"10":61,"15":52,"20":44,"25":36,"scratch":78}}', 20);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('long-iron-fairway', 'Long-Iron Fairway Finder', 'approach', '10 shots with 4/5-iron into a 25yd-wide fairway window.', '{"scoring":"percent_success","reps":10,"targets":{"5":60,"10":50,"15":40,"20":32,"25":24,"scratch":70}}', 15);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('fairway-14', '14 Fairways', 'driving', '14 drives into a 35yd-wide window (your course''s average fairway).', '{"scoring":"percent_success","reps":14,"targets":{"5":62,"10":53,"15":45,"20":37,"25":29,"scratch":71}}', 25);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('shot-shape-tee', 'Tee-Shot Shapes', 'driving', 'Alternate called fades and draws off the tee. Success = called curve, playable line.', '{"scoring":"percent_success","reps":10,"targets":{"5":50,"10":40,"15":31,"20":24,"25":17,"scratch":60}}', 20);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('pressure-driver', 'Pressure Ladder', 'driving', 'Consecutive fairway hits build points (1,2,3...); a miss resets. Score = best streak points ÷ max.', '{"scoring":"points","reps":10,"targets":{"5":45,"10":36,"15":28,"20":21,"25":15,"scratch":55}}', 20);
insert into practice_drills (slug, title, category, description, rubric, est_minutes) values ('tempo-75', '75% Tempo Drives', 'driving', '10 drives at 75% effort into the window — trains sequencing.', '{"scoring":"percent_success","reps":10,"targets":{"5":66,"10":57,"15":48,"20":40,"25":32,"scratch":75}}', 15);
